package io.github.kotlinmania.unicodesegmentation

/** The version of Unicode that this version of unicode-segmentation is based on. */
val UNICODE_VERSION: Triple<Int, Int, Int> = Triple(16, 0, 0)

internal data class CodePointRange(val lower: Int, val upper: Int)

internal data class CategoryRange<T>(val lower: Int, val upper: Int, val category: T)

internal data class CategoryResult<T>(val lower: Int, val upper: Int, val category: T)

internal data class CodePointSpan(val codePoint: Int, val start: Int, val end: Int)

internal fun String.nextCodePointSpan(index: Int): CodePointSpan? {
    if (index >= length) return null
    val first = this[index]
    if (first.code in 0xD800..0xDBFF && index + 1 < length) {
        val second = this[index + 1]
        if (second.code in 0xDC00..0xDFFF) {
            val value = 0x10000 + ((first.code - 0xD800) shl 10) + (second.code - 0xDC00)
            return CodePointSpan(value, index, index + 2)
        }
    }
    return CodePointSpan(first.code, index, index + 1)
}

internal fun String.previousCodePointSpan(index: Int): CodePointSpan? {
    if (index <= 0) return null
    val last = this[index - 1]
    if (last.code in 0xDC00..0xDFFF && index >= 2) {
        val first = this[index - 2]
        if (first.code in 0xD800..0xDBFF) {
            val value = 0x10000 + ((first.code - 0xD800) shl 10) + (last.code - 0xDC00)
            return CodePointSpan(value, index - 2, index)
        }
    }
    return CodePointSpan(last.code, index - 1, index)
}

internal fun String.codePointSpans(): List<CodePointSpan> {
    val spans = mutableListOf<CodePointSpan>()
    var index = 0
    while (index < length) {
        val span = nextCodePointSpan(index) ?: break
        spans.add(span)
        index = span.end
    }
    return spans
}

private fun decodeCodePointRanges(data: String): List<CodePointRange> {
    if (data.isEmpty()) return emptyList()
    return data.split(";").filter { it.isNotEmpty() }.map { entry ->
        val parts = entry.split(",")
        CodePointRange(parts[0].toInt(16), parts[1].toInt(16))
    }
}

private fun <T> decodeCategoryRanges(data: String, categories: List<T>): List<CategoryRange<T>> {
    if (data.isEmpty()) return emptyList()
    return data.split(";").filter { it.isNotEmpty() }.map { entry ->
        val parts = entry.split(",")
        CategoryRange(parts[0].toInt(16), parts[1].toInt(16), categories[parts[2].toInt(16)])
    }
}

internal fun bsearchRangeTable(codePoint: Int, ranges: List<CodePointRange>): Boolean {
    var low = 0
    var high = ranges.lastIndex
    while (low <= high) {
        val mid = (low + high) ushr 1
        val range = ranges[mid]
        when {
            codePoint < range.lower -> high = mid - 1
            codePoint > range.upper -> low = mid + 1
            else -> return true
        }
    }
    return false
}

private fun <T> bsearchRangeValueTable(
    codePoint: Int,
    ranges: List<CategoryRange<T>>,
    defaultLower: Int,
    defaultUpper: Int,
    defaultCategory: T,
): CategoryResult<T> {
    var low = 0
    var high = ranges.lastIndex
    var insertion = 0
    while (low <= high) {
        val mid = (low + high) ushr 1
        val range = ranges[mid]
        when {
            codePoint < range.lower -> {
                insertion = mid
                high = mid - 1
            }
            codePoint > range.upper -> {
                insertion = mid + 1
                low = mid + 1
            }
            else -> return CategoryResult(range.lower, range.upper, range.category)
        }
    }
    val lower = if (insertion > 0) ranges[insertion - 1].upper + 1 else defaultLower
    val upper = if (insertion < ranges.size) ranges[insertion].lower - 1 else defaultUpper
    return CategoryResult(lower, upper, defaultCategory)
}

internal fun isAlphanumeric(codePoint: Int): Boolean =
    isAlphabetic(codePoint) || isNumeric(codePoint)

private fun isAlphabetic(codePoint: Int): Boolean =
    when {
        codePoint in 0x41..0x5A || codePoint in 0x61..0x7A -> true
        codePoint > 0x7F -> DerivedProperty.alphabetic(codePoint)
        else -> false
    }

private fun isNumeric(codePoint: Int): Boolean =
    when {
        codePoint in 0x30..0x39 -> true
        codePoint > 0x7F -> GeneralCategory.n(codePoint)
        else -> false
    }

internal object GeneralCategory {
    fun n(codePoint: Int): Boolean = bsearchRangeTable(codePoint, N_TABLE)
}

private val N_TABLE: List<CodePointRange> by lazy { decodeCodePointRanges(nTableData()) }

