internal fun isIncbLinker(codePoint: Int): Boolean =
    codePoint == 0x94D || codePoint == 0x9CD || codePoint == 0xACD ||
        codePoint == 0xB4D || codePoint == 0xC4D || codePoint == 0xD4D

internal enum class GraphemeCat {
    Any,
    Cr,
    Control,
    Extend,
    ExtendedPictographic,
    InCbConsonant,
    L,
    Lf,
    Lv,
    LvT,
    Prepend,
    RegionalIndicator,
    SpacingMark,
    T,
    V,
    Zwj,
}

internal fun graphemeCategory(codePoint: Int): CategoryResult<GraphemeCat> {
    if (codePoint <= 0x7E) {
        return when {
            codePoint >= 0x20 -> CategoryResult(codePoint, codePoint, GraphemeCat.Any)
            codePoint == 0x0A -> CategoryResult(codePoint, codePoint, GraphemeCat.Lf)
            codePoint == 0x0D -> CategoryResult(codePoint, codePoint, GraphemeCat.Cr)
            else -> CategoryResult(codePoint, codePoint, GraphemeCat.Control)
        }
    }
    return bsearchRangeValueTable(codePoint, GRAPHEME_CAT_TABLE, 0, 0x10FFFF, GraphemeCat.Any)
}

private val GRAPHEME_CAT_TABLE: List<CategoryRange<GraphemeCat>> by lazy {
